def transform(g):
 # identify rectangular objects via nonzero components; all are frames or pattern source
 from collections import deque
 H,W=len(g),len(g[0]); seen=set(); comps=[]
 for r in range(H):
  for c in range(W):
   if g[r][c] and (r,c) not in seen:
    q=[(r,c)];seen.add((r,c)); cells=[]
    while q:
     y,x=q.pop();cells.append((y,x))
     for yy,xx in ((y+1,x),(y-1,x),(y,x+1),(y,x-1)):
      if 0<=yy<H and 0<=xx<W and g[yy][xx] and (yy,xx) not in seen:seen.add((yy,xx));q.append((yy,xx))
    comps.append((min(y for y,x in cells),max(y for y,x in cells),min(x for y,x in cells),max(x for y,x in cells),g[r][c]))
 # frames are rectangular bounds; choose object with interior nonzero, distinguish source
 src=None
 for t,b,l,r,col in comps:
  if all(g[t][x]==col and g[b][x]==col for x in range(l,r+1)) and all(g[y][l]==col and g[y][r]==col for y in range(t,b+1)):
   inner=[[g[y][x] for x in range(l+1,r)] for y in range(t+1,b)]
   if any(v==col for row in inner for v in row):src=(t,b,l,r,col,inner);break
 out=[row[:] for row in g]
 if src:
  t,b,l,r,col,pat=src; ph=len(pat);pw=len(pat[0])
  for a,z,x,w,c in comps:
   if c==col or not (all(g[a][j]==c and g[z][j]==c for j in range(x,w+1)) and all(g[i][x]==c and g[i][w]==c for i in range(a,z+1))):continue
   for y in range(a+1,z):
    for xx in range(x+1,w):
     if pat[(y-a-1)%ph][(xx-x-1)%pw]:out[y][xx]=c
 return out
